import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Main {
    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        String token = sc.next();
        if (token == null) return;
        int n = Integer.parseInt(token);

        int[] raw = new int[n];
        for (int i = 0; i < n; i++) {
            raw[i] = sc.nextInt();
        }

        // Remove duplicatas consecutivas
        List<Integer> list = new ArrayList<>(n + 2);
        list.add(0); // Sentinela à esquerda
        for (int i = 0; i < n; i++) {
            if (i == 0 || raw[i] != raw[i - 1]) {
                list.add(raw[i]);
            }
        }
        list.add(0); // Sentinela à direita

        int m = list.size();
        int[] a = new int[m];
        for (int i = 0; i < m; i++) {
            a[i] = list.get(i);
        }

        // Agrupa os índices por altura (excluindo as sentinelas)
        Map<Integer, List<Integer>> heightIndices = new HashMap<>();
        for (int i = 1; i < m - 1; i++) {
            heightIndices.computeIfAbsent(a[i], k -> new ArrayList<>()).add(i);
        }

        List<Integer> uniqueHeights = new ArrayList<>(heightIndices.keySet());
        Collections.sort(uniqueHeights);

        // Para H logo acima de 0 (0 < H < menor altura), temos 1 componente
        int currentComponents = 1;
        int maxComponents = 1;

        for (int h : uniqueHeights) {
            List<Integer> indices = heightIndices.get(h);
            for (int idx : indices) {
                if (a[idx] > a[idx - 1] && a[idx] > a[idx + 1]) {
                    // Pico local: a componente desaparece quando o corte passa dessa altura
                    currentComponents--;
                } else if (a[idx] < a[idx - 1] && a[idx] < a[idx + 1]) {
                    // Vale local: a componente se divide em duas quando o corte passa dessa altura
                    currentComponents++;
                }
            }
            if (currentComponents > maxComponents) {
                maxComponents = currentComponents;
            }
        }

        // O número total de pedaços é o número de componentes superiores + 1 (base inferior)
        System.out.println(maxComponents + 1);
    }
}
