import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;
import java.util.Comparator;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= 32 && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            int res = 0;
            while (b > 32) {
                if (b >= '0' && b <= '9') {
                    res = res * 10 + (b - '0');
                }
                b = readByte();
            }
            return res;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n <= 0) {
            System.out.println(1);
            return;
        }

        // Lê alturas e comprime elementos adjacentes iguais
        int[] raw = new int[n];
        for (int i = 0; i < n; i++) {
            raw[i] = scanner.nextInt();
        }

        // Comprime adjacentes iguais e adiciona sentinelas com altura 0 nas pontas
        int m = 0;
        int[] h = new int[n + 2];
        h[m++] = 0; // sentinela esquerda

        for (int i = 0; i < n; i++) {
            if (i == 0 || raw[i] != raw[i - 1]) {
                h[m++] = raw[i];
            }
        }
        h[m++] = 0; // sentinela direita

        // Índices de 1 a m - 2
        int count = m - 2;
        Integer[] order = new Integer[count];
        for (int i = 0; i < count; i++) {
            order[i] = i + 1;
        }

        // Ordena índices em ordem decrescente de altura
        Arrays.sort(order, new Comparator<Integer>() {
            @Override
            public int compare(Integer a, Integer b) {
                return Integer.compare(h[b], h[a]);
            }
        });

        boolean[] active = new boolean[m];
        int currentComponents = 0;
        int maxPieces = 1;

        int i = 0;
        while (i < count) {
            int currentH = h[order[i]];
            int j = i;
            while (j < count && h[order[j]] == currentH) {
                int idx = order[j];
                active[idx] = true;
                boolean left = active[idx - 1];
                boolean right = active[idx + 1];

                if (!left && !right) {
                    currentComponents++;
                } else if (left && right) {
                    currentComponents--;
                }
                j++;
            }

            int pieces = currentComponents + 1;
            if (pieces > maxPieces) {
                maxPieces = pieces;
            }

            i = j;
        }

        System.out.println(maxPieces);
    }
}
